CREATE DATABASE IF NOT EXISTS mini_amazon_db;
USE mini_amazon_db;
CREATE TABLE users (id_user INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, address VARCHAR(200), telephone VARCHAR(20), role VARCHAR(20) NOT NULL DEFAULT 'customer');
CREATE TABLE categories (id_category INT PRIMARY KEY AUTO_INCREMENT, category_name VARCHAR(100) NOT NULL);
CREATE TABLE products (id_product INT PRIMARY KEY AUTO_INCREMENT, product_name VARCHAR(150) NOT NULL, description TEXT, fabrication_year INT, manufacturer VARCHAR(100) NOT NULL DEFAULT '', price DECIMAL(10,2) NOT NULL, stock INT NOT NULL, id_category INT, image VARCHAR(500), FOREIGN KEY(id_category) REFERENCES categories(id_category));
CREATE TABLE cart (id_cart INT PRIMARY KEY AUTO_INCREMENT, id_user INT NOT NULL UNIQUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(id_user) REFERENCES users(id_user));
CREATE TABLE cart_detail (id_cart_detail INT PRIMARY KEY AUTO_INCREMENT, id_cart INT NOT NULL, id_product INT NOT NULL, quantity INT NOT NULL, FOREIGN KEY(id_cart) REFERENCES cart(id_cart), FOREIGN KEY(id_product) REFERENCES products(id_product));
CREATE TABLE orders (id_order INT PRIMARY KEY AUTO_INCREMENT, id_user INT NOT NULL, order_date DATETIME DEFAULT CURRENT_TIMESTAMP, total DECIMAL(10,2) NOT NULL, status VARCHAR(50) DEFAULT 'Pending', FOREIGN KEY(id_user) REFERENCES users(id_user));
CREATE TABLE order_detail (id_order_detail INT PRIMARY KEY AUTO_INCREMENT, id_order INT NOT NULL, id_product INT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY(id_order) REFERENCES orders(id_order), FOREIGN KEY(id_product) REFERENCES products(id_product));
CREATE TABLE payments (id_payment INT PRIMARY KEY AUTO_INCREMENT, id_order INT NOT NULL, payment_method VARCHAR(50), amount DECIMAL(10,2), payment_date DATETIME DEFAULT CURRENT_TIMESTAMP, payment_status VARCHAR(50), FOREIGN KEY(id_order) REFERENCES orders(id_order));
CREATE TABLE roles (roleId VARCHAR(50) PRIMARY KEY, role_name VARCHAR(50) NOT NULL UNIQUE, role_description VARCHAR(150));
CREATE TABLE roleuser (UserName VARCHAR(50) NOT NULL, RoleId VARCHAR(50) NOT NULL, dateAssign DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(UserName,RoleId));
CREATE TABLE rolewebpagegood (RoleId VARCHAR(50), pageURL VARCHAR(100), dateAssign DATETIME DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(RoleId,pageURL));
CREATE TABLE webpagegood (pageURL VARCHAR(100) PRIMARY KEY, pageTitle VARCHAR(100), Description VARCHAR(255), menuID INT);
CREATE TABLE webpageprevious (currentpageURL VARCHAR(100), previouspageURL VARCHAR(100));
CREATE TABLE usergood (UserName VARCHAR(50) PRIMARY KEY, hashing VARCHAR(255), Name VARCHAR(100), Telephone VARCHAR(50), Email VARCHAR(100), Address VARCHAR(200));
